    internal static int LtItem(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, int parent, byte[] marker, byte[] body, int scheme, int value, int x) {
        // An `item` of the old Model under parent: its marker, text, scheme (`sub`), value (`aux`), text x (`fk-box`).
        int it = Model.NodeNew(nodes, Model.NkItem(), parent);
        int t0 = emon.Port.CellsLen(text);
        Model.TextAppendUtf8(text, body, 0, emon.Port.BlobLen(body));
        Model.NodeSetText(nodes, it, t0, emon.Port.CellsLen(text) - t0);
        int m0 = emon.Port.CellsLen(text);
        Model.TextAppendUtf8(text, marker, 0, emon.Port.BlobLen(marker));
        Model.NodeSetAttrText(nodes, attrs, it, Model.FkMarker(), m0, emon.Port.CellsLen(text) - m0);
        Model.NodeSetSub(nodes, it, scheme);
        Model.NodeSetAux(nodes, it, value);
        Model.NodeSetAttrInt(nodes, attrs, it, Model.FkBox(), x);
        return it;
    }
