    [Xunit.Fact]
    public static void TestItemsBecomeListsNestedByTheXOfTheirText() {
        emon.Port.Cells on = emon.Port.NewCells();
        emon.Port.Cells oa = emon.Port.NewCells();
        emon.Port.Cells orr = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        Model.ModelInit(on, oa, orr, text, pages, ledger, layout);
        int sec = Model.NodeNew(on, Model.NkSection(), 0);
        LtItem(on, oa, text, sec, emon.Testport.TextBlob("1."), emon.Testport.TextBlob("one"), Lists.LsScDecimal(), 1, 9000);
        LtItem(on, oa, text, sec, emon.Testport.TextBlob("2."), emon.Testport.TextBlob("two"), Lists.LsScDecimal(), 2, 9000);
        LtItem(on, oa, text, sec, emon.Testport.TextBlob("a."), emon.Testport.TextBlob("inner a"), Lists.LsScLowerAlpha(), 1, 12000);
        LtItem(on, oa, text, sec, emon.Testport.TextBlob("b."), emon.Testport.TextBlob("inner b"), Lists.LsScLowerAlpha(), 2, 12000);
        LtItem(on, oa, text, sec, emon.Testport.TextBlob("3."), emon.Testport.TextBlob("three"), Lists.LsScDecimal(), 3, 9000);
        LtItem(on, oa, text, sec, emon.Testport.TextBlob("5."), emon.Testport.TextBlob("five"), Lists.LsScDecimal(), 5, 9000);
        Model.NodeNew(on, Model.NkParagraph(), sec);
        LtItem(on, oa, text, sec, emon.Testport.TextBlob("1."), emon.Testport.TextBlob("again"), Lists.LsScDecimal(), 1, 9000);
        emon.Testport.AssertEq(LtRs(on, oa, orr, text, nodes, attrs, regions), 13, "seven items, two lists and a nested one, a paragraph");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 0), 1, "the document");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 2), Model.NkList(), "the first item opens a list under the section");
        emon.Testport.AssertEq(Model.NodeParent(nodes, 2), 1, "in the section");
        emon.Testport.AssertEq(Model.NodeSub(nodes, 2), 2, "an ordered one");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 3), Model.NkItem(), "its first item");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 5), Model.NkList(), "the lettered items are a list of their own");
        emon.Testport.AssertEq(Model.NodeParent(nodes, 5), 4, "inside the item before them");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 8), Model.NkItem(), "then the third item continues the numbered list");
        emon.Testport.AssertEq(Model.NodeParent(nodes, 8), 2, "in the outer list");
        emon.Testport.AssertEq(Model.NodeAttrIntOr(nodes, attrs, 9, Model.FkValue(), -1), 5, "the item that skips gets an explicit value");
        emon.Testport.AssertEq(Model.NodeAttrIntOr(nodes, attrs, 8, Model.FkValue(), -1), -1, "and the one that does not, none");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 10), Model.NkParagraph(), "a paragraph ends the list");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 11), Model.NkList(), "and a numbering that starts again is a new list");
        emon.Testport.AssertEq(Model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "the new Model is in document order");
    }
