        LtItem(on, oa, text, 0, emon.Testport.TextBlob("2."), emon.Testport.TextBlob("two"), Lists.LsScDecimal(), 2, 9000);
        int br = Model.NodeNew(on, Model.NkBreak(), 0);
        Model.NodeSetSub(on, br, 2);
        LtItem(on, oa, text, 0, emon.Testport.TextBlob("3."), emon.Testport.TextBlob("three"), Lists.LsScDecimal(), 3, 9000);
        emon.Testport.AssertEq(LtRs(on, oa, orr, text, nodes, attrs, regions), 6, "one list, three items, the milestone in the second");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 1), Model.NkList(), "a list");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 3), Model.NkItem(), "an item");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 4), Model.NkBreak(), "the milestone is in it");
        emon.Testport.AssertEq(Model.NodeParent(nodes, 4), 3, "kept in the item before it");
        emon.Testport.AssertEq(Model.NodeParent(nodes, 5), 1, "and the next item is in the same list");
        emon.Testport.AssertEq(Model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
    }
    internal static int LtCaption(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, int parent, int kind) {
        // A caption of the old Model (its kind in `aux`) with a label and a text.
        int c = Model.NodeNew(nodes, Model.NkCaption(), parent);
        int t0 = emon.Port.CellsLen(text);
        byte[] b = emon.Testport.TextBlob("Table 1");
        Model.TextAppendUtf8(text, b, 0, emon.Port.BlobLen(b));
        Model.NodeSetAttrText(nodes, attrs, c, Model.FkLabel(), t0, emon.Port.CellsLen(text) - t0);
        Model.NodeSetAux(nodes, c, kind);
        return c;
    }
    [Xunit.Fact]
    public static void TestACaptionIsBoundToItsObject() {
        emon.Port.Cells on = emon.Port.NewCells();
        emon.Port.Cells oa = emon.Port.NewCells();
        emon.Port.Cells orr = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        Model.ModelInit(on, oa, orr, text, pages, ledger, layout);
        LtCaption(on, oa, text, 0, 2);
        Model.NodeNew(on, Model.NkTable(), 0);
        Model.NodeNew(on, Model.NkParagraph(), 0);
        LtCaption(on, oa, text, 0, 1);
        emon.Testport.AssertEq(LtRs(on, oa, orr, text, nodes, attrs, regions), 6, "a table with its caption, a paragraph, a figure with its caption");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 1), Model.NkTable(), "the table first");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 2), Model.NkCaption(), "its caption is its first child");
        emon.Testport.AssertEq(Model.NodeParent(nodes, 2), 1, "of it");
        emon.Testport.AssertEq(Model.NodeAttrIntOr(nodes, attrs, 2, Model.FkTarget(), -1), 1, "and points at it");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 3), Model.NkParagraph(), "the paragraph");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 4), Model.NkFigure(), "a figure caption with no figure is wrapped in an empty figure");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 5), Model.NkCaption(), "the caption is inside it");
        emon.Testport.AssertEq(Model.NodeAttrIntOr(nodes, attrs, 5, Model.FkTarget(), -1), 4, "pointing at it");
        emon.Testport.AssertEq(Model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
    }
    [Xunit.Fact]
    public static void TestNoteReferencesFindTheirNotesAndBareLinksBecomeLinks() {
        emon.Port.Cells on = emon.Port.NewCells();
        emon.Port.Cells oa = emon.Port.NewCells();
        emon.Port.Cells orr = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        Model.ModelInit(on, oa, orr, text, pages, ledger, layout);
        int p = Model.NodeNew(on, Model.NkParagraph(), 0);
        int t1 = Model.NodeNew(on, Model.NkText(), p);
        int r = Model.NodeNew(on, Model.NkRef(), p);
        int nt = Model.NodeNew(on, Model.NkNote(), 0);
        int np = Model.NodeNew(on, Model.NkParagraph(), nt);
        byte[] b = emon.Testport.TextBlob("see www.example.com now");
        byte[] m = emon.Testport.TextBlob("1");
        int s0 = emon.Port.CellsLen(text);
        Model.TextAppendUtf8(text, b, 0, emon.Port.BlobLen(b));
        Model.NodeSetText(on, t1, s0, emon.Port.CellsLen(text) - s0);
        int m0 = emon.Port.CellsLen(text);
        Model.TextAppendUtf8(text, m, 0, emon.Port.BlobLen(m));
        Model.NodeSetAttrText(on, oa, r, Model.FkMarker(), m0, 1);
        Model.NodeSetAttrText(on, oa, nt, Model.FkMarker(), m0, 1);
        int s1 = emon.Port.CellsLen(text);
        Model.TextAppendUtf8(text, b, 0, emon.Port.BlobLen(b));
        Model.NodeSetText(on, np, s1, emon.Port.CellsLen(text) - s1);
        emon.Testport.AssertEq(LtRs(on, oa, orr, text, nodes, attrs, regions), 13, "the paragraph, the text split in three, the ref, the note");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 2), Model.NkText(), "the text before the link");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 3), Model.NkLink(), "the link");
        emon.Testport.AssertEq(Model.NodeFirstChild(nodes, 3), 4, "holding its text");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 5), Model.NkText(), "the text after it");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 6), Model.NkRef(), "the reference");
        emon.Testport.AssertEq(Model.NodeAttrIntOr(nodes, attrs, 6, Model.FkTarget(), -1), 7, "has the note as its target");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 7), Model.NkNote(), "the note");
        emon.Testport.AssertEq(Model.NodeKind(nodes, 10), Model.NkLink(), "and the bare link in the note's own text is a link as well");
        emon.Testport.AssertEq(Model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
    }
